import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SummaryStatistics.toString()
 */
public class SummaryStatistics_toString_TriageGen2Test {

    @Test
    public void testToStringWithData() {
        SummaryStatistics stats = new SummaryStatistics();
        stats.addValue(1.0);
        stats.addValue(2.0);
        stats.addValue(4.0);

        String result = stats.toString();

        // Expected values based on input {1.0, 2.0, 4.0}
        // n=3, min=1.0, max=4.0, mean=2.333..., geoMean=2.0, variance=4.333..., sumsq=21.0, stdDev=2.081..., sumLogs=...

        Assert.assertTrue("Should contain header", result.contains("SummaryStatistics:"));
        Assert.assertTrue("Should contain n", result.contains("n: 3"));
        Assert.assertTrue("Should contain min", result.contains("min: 1.0"));
        Assert.assertTrue("Should contain max", result.contains("max: 4.0"));
        Assert.assertTrue("Should contain mean", result.contains("mean: 2.3333333333333335"));
        Assert.assertTrue("Should contain geometric mean", result.contains("geometric mean: 2.0"));
        Assert.assertTrue("Should contain variance", result.contains("variance: 4.333333333333333"));
        Assert.assertTrue("Should contain sum of squares", result.contains("sum of squares: 21.0"));
        Assert.assertTrue("Should contain standard deviation", result.contains("standard deviation: 2.0816659994661326"));
        Assert.assertTrue("Should contain sum of logs", result.contains("sum of logs: 2.0794415416798357"));
    }






}

