/**
 * Unit tests for SummaryStatistics.toString()
 */
public class SummaryStatistics_toString_TriageGen2Test {



    @Test
    public void testToStringEmpty() {
        SummaryStatistics stats = new SummaryStatistics();
        String result = stats.toString();

        // When empty, Apache Commons Math typically returns NaN or 0/Infinity for various stats
        Assert.assertTrue(result.contains("SummaryStatistics:"));
        Assert.assertTrue("n should be 0", result.contains("n: 0"));
        Assert.assertTrue("min should be NaN", result.contains("min: NaN"));
        Assert.assertTrue("max should be NaN", result.contains("max: NaN"));
        Assert.assertTrue("mean should be NaN", result.contains("mean: NaN"));
        Assert.assertTrue("geometric mean should be NaN", result.contains("geometric mean: NaN"));
        Assert.assertTrue("variance should be NaN", result.contains("variance: NaN"));
        Assert.assertTrue("sum of squares should be 0.0", result.contains("sum of squares: 0.0"));
        Assert.assertTrue("std dev should be NaN", result.contains("standard deviation: NaN"));
        Assert.assertTrue("sum of logs should be 0.0", result.contains("sum of logs: 0.0"));
    }




}

