/**
 * Unit tests for SummaryStatistics.toString()
 */
public class SummaryStatistics_toString_TriageGen2Test {







    @Test
    public void testToStringWithNegativeValues() {
        // Note: Geometric mean is typically undefined/NaN for negative numbers
        SummaryStatistics stats = new SummaryStatistics();
        stats.addValue(-1.0);
        stats.addValue(-2.0);
        String result = stats.toString();

        Assert.assertTrue(result.contains("n: 2"));
        Assert.assertTrue(result.contains("min: -2.0"));
        Assert.assertTrue(result.contains("max: -1.0"));
        // Geometric mean for negative numbers in this implementation returns NaN
        Assert.assertTrue(result.contains("geometric mean: NaN"));
    }
}
